        TAG_LUXURY,
        TAG_STABLE,
        TAG_DOPAMINE,
        TAG_RELAX,
        TAG_PACKED,
        THEME_PALACE_CULTURE_YN,
        THEME_NATURE_HANGANG_YN,
        THEME_DATE_YN,
        THEME_FOOD_TOUR_YN,
        THEME_CAFE_TOUR_YN,
