        S.RATING,
        S.REVIEW_COUNT,
        S.DESCRIPTION,
        S.IMAGE_URL,
        S.IMAGE_SOURCE,
        CASE
            WHEN S.IMAGE_MATCH_SCORE IS NULL THEN NULL
            ELSE LEAST(100, GREATEST(0, S.IMAGE_MATCH_SCORE))
        END,
        S.IMAGE_STATUS,
        S.IMAGE_LICENSE_TYPE,
        S.IMAGE_ATTRIBUTION,
        S.TAG_HISTORY,
        S.TAG_MODERN,
        S.TAG_BUDGET,
        S.TAG_LUXURY,
        S.TAG_STABLE,
        S.TAG_DOPAMINE,
        S.TAG_RELAX,
        S.TAG_PACKED,
        S.THEME_PALACE_CULTURE_YN,
        S.THEME_NATURE_HANGANG_YN,
        S.THEME_DATE_YN,
        S.THEME_FOOD_TOUR_YN,
